CREATE TABLE run_daily_exceptions (run_id TEXT PRIMARY KEY REFERENCES runs(id),quote_id TEXT NOT NULL UNIQUE REFERENCES quotes(id),actor TEXT NOT NULL CHECK(length(actor)>0),build TEXT NOT NULL CHECK(length(build)=40 AND build NOT GLOB '*[^0-9a-f]*'),provider TEXT NOT NULL CHECK(provider='deepseek'),model_id TEXT NOT NULL CHECK(model_id='deepseek-flash'),mode TEXT NOT NULL CHECK(mode='unlimited'),fingerprints_json TEXT NOT NULL CHECK(json_valid(fingerprints_json) AND json_type(fingerprints_json)='array' AND json_array_length(fingerprints_json)>0),start_at TEXT NOT NULL,end_at TEXT NOT NULL,granted_at TEXT NOT NULL,CHECK(start_at<=granted_at AND granted_at<end_at AND strftime('%Y-%m-%dT%H:%M:%fZ',granted_at) IS granted_at));
CREATE INDEX run_daily_exceptions_scope ON run_daily_exceptions(actor,provider,model_id,start_at,end_at);
CREATE TRIGGER run_daily_exception_immutable_update BEFORE UPDATE ON run_daily_exceptions BEGIN SELECT RAISE(ABORT,'Run allowance records are immutable.'); END;
CREATE TRIGGER run_daily_exception_immutable_delete BEFORE DELETE ON run_daily_exceptions BEGIN SELECT RAISE(ABORT,'Run allowance records are immutable.'); END;
ALTER TABLE daily_usage_reservations RENAME TO daily_usage_reservations_prior;
ALTER TABLE daily_usage_cancellations RENAME TO daily_usage_cancellations_prior;
CREATE TABLE daily_usage_reservations (attempt_id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(id),model_id TEXT NOT NULL,pool TEXT NOT NULL,unit TEXT NOT NULL CHECK(unit IN ('tokens','nanodollars')),day TEXT NOT NULL,reserved_units INTEGER NOT NULL CHECK(reserved_units>0 AND reserved_units<=9007199254740991),limit_units INTEGER,owner_nonce TEXT NOT NULL,created_at TEXT NOT NULL,CHECK((limit_units IS NOT NULL AND limit_units>0 AND limit_units<=9007199254740991 AND pool NOT LIKE 'deepseek/run/%') OR (limit_units IS NULL AND pool='deepseek/run/'||run_id AND model_id='deepseek-flash' AND unit='nanodollars')));
INSERT INTO daily_usage_reservations SELECT * FROM daily_usage_reservations_prior;
CREATE TABLE daily_usage_cancellations (attempt_id TEXT PRIMARY KEY REFERENCES daily_usage_reservations(attempt_id),owner_nonce TEXT NOT NULL,created_at TEXT NOT NULL,reason TEXT NOT NULL);
INSERT INTO daily_usage_cancellations SELECT * FROM daily_usage_cancellations_prior;
DROP TABLE daily_usage_cancellations_prior;
DROP TABLE daily_usage_reservations_prior;
CREATE INDEX daily_usage_pool_day ON daily_usage_reservations(pool,day);
CREATE TRIGGER run_daily_exception_reserve BEFORE INSERT ON daily_usage_reservations WHEN NEW.limit_units IS NULL AND NOT EXISTS(SELECT 1 FROM run_daily_exceptions e JOIN runs r ON r.id=e.run_id JOIN controls k ON k.id=1 WHERE e.run_id=NEW.run_id AND NEW.model_id=e.model_id AND NEW.pool=e.provider||'/run/'||e.run_id AND e.start_at<=NEW.created_at AND NEW.created_at<e.end_at AND r.status='running' AND r.actor=e.actor AND r.quote_id=e.quote_id AND k.kill=0) BEGIN SELECT RAISE(ABORT,'No active run-specific daily allowance.'); END;
CREATE TRIGGER run_daily_exception_enroll BEFORE INSERT ON run_daily_exceptions WHEN NOT EXISTS(SELECT 1 FROM runs r JOIN quotes q ON q.id=r.quote_id JOIN controls k ON k.id=1 WHERE r.id=NEW.run_id AND r.quote_id=NEW.quote_id AND r.actor=NEW.actor AND q.actor=NEW.actor AND r.created_at<=NEW.granted_at AND q.created_at<=NEW.granted_at AND r.status='uploading' AND r.mode='interactive' AND k.kill=0 AND json_extract(r.pack_json,'$.pins.reader.id')=NEW.model_id AND json_extract(r.pack_json,'$.selectedReaderModel')=NEW.provider AND json_extract(r.pack_json,'$.settings.inferenceWindow.startAt')=NEW.start_at AND json_extract(r.pack_json,'$.settings.inferenceWindow.endAt')=NEW.end_at AND json_extract(r.budget_json,'$.mode')='unlimited' AND json_extract(r.budget_json,'$.actor')=NEW.actor AND json_type(r.budget_json,'$.unlimitedAcknowledged')='true' AND json_type(r.budget_json,'$.limits.blended')='null' AND json_type(r.budget_json,'$.limits.openai')='null' AND json_type(r.budget_json,'$.limits.typesafe')='null' AND NEW.start_at<=r.created_at AND r.created_at<NEW.end_at AND json_extract(r.pack_json,'$.settings.usageLimits.deepseekDailyNano') IS NOT NULL AND r.expected_count=json_array_length(NEW.fingerprints_json) AND r.expected_count=(SELECT COUNT(*) FROM quote_documents d WHERE d.quote_id=q.id) AND NOT EXISTS(SELECT 1 FROM json_each(NEW.fingerprints_json) j LEFT JOIN quote_documents d ON d.quote_id=q.id AND d.ordinal=j.key+1 WHERE j.type!='text' OR length(j.value)!=64 OR j.value GLOB '*[^0-9a-f]*' OR d.fingerprint IS NOT j.value) AND NOT EXISTS(SELECT 1 FROM documents x WHERE x.run_id=r.id) AND NOT EXISTS(SELECT 1 FROM checkpoints c WHERE c.run_id=r.id) AND NOT EXISTS(SELECT 1 FROM vendor_calls v WHERE v.run_id=r.id) AND NOT EXISTS(SELECT 1 FROM workflow_dispatch_admissions a WHERE a.run_id=r.id) AND NOT EXISTS(SELECT 1 FROM daily_usage_reservations h WHERE h.run_id=r.id)) OR EXISTS(SELECT 1 FROM run_daily_exceptions old JOIN json_each(old.fingerprints_json) prev JOIN json_each(NEW.fingerprints_json) next ON next.value=prev.value WHERE old.actor=NEW.actor AND old.provider=NEW.provider AND old.model_id=NEW.model_id AND old.start_at<NEW.end_at AND NEW.start_at<old.end_at) BEGIN SELECT RAISE(ABORT,'The run cannot be enrolled for this provider allowance.'); END;
